begin;
set local search_path = public, extensions;
do $world_pulse_seed$
declare
  v_world uuid;
  v_location uuid;
  v_primary uuid;
  v_template uuid;
  v_character uuid;
  v_existing record;
  v_facts jsonb;
  v_known_ids jsonb;
begin
  select id into strict v_world from public.together_worlds where slug = 'eos-meridian' and published;
  insert into public.together_world_pulse_settings (world_id, enabled) values (v_world, false) on conflict (world_id) do nothing;
  select id into strict v_location from public.together_locations where world_id = v_world and slug = 'meridian-concourse' and owner_user_id is null and archived_at is null;
  select id into strict v_primary from public.together_character_templates where slug = 'mara-venn' and published and creator_id is null;
  select id, repeat_identity, scheduling_rank, content_version, metadata into v_existing from public.together_world_pulse_templates where world_id = v_world and slug = 'eleven-minutes-without-the-horizon';
  if found and (v_existing.repeat_identity <> 'eos-meridian:major:eleven-minutes-without-the-horizon' or v_existing.scheduling_rank <> 200 or v_existing.content_version > 1 or coalesce(v_existing.metadata->>'pulseTier', 'routine') <> 'major') then raise exception 'Unsafe Pulse identity, rank, tier or version edit: eos-meridian/eleven-minutes-without-the-horizon'; end if;
  v_facts := '[]'::jsonb;
  select coalesce(jsonb_agg(id::text order by id), '[]'::jsonb) into v_known_ids from public.together_character_templates where slug = any(array['mara-venn','kellan-ro','zoe-mercer']::text[]) and published and creator_id is null;
  if jsonb_array_length(v_known_ids) <> 3 then raise exception 'Unknown Pulse fact knower: eos-meridian/eleven-minutes-without-the-horizon/public-report'; end if;
  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','A fast dust front erases the copper horizon while a school rover is still returning. Transit finds the rover, but its beacon keeps broadcasting from the wrong side of the storm.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'eleven-minutes-without-the-horizon','eos-meridian:major:eleven-minutes-without-the-horizon',200,1,'Eleven Minutes Without the Horizon','A fast dust front erases the copper horizon while a school rover is still returning. Transit finds the rover, but its beacon keeps broadcasting from the wrong side of the storm.','On Eos Meridian, the settlement sits between a sunlit desert and permanent night. When a dust front crosses the daylight edge, every outward window turns brown at once. A rover carrying Pressure School students is due back in eleven minutes; its live position suddenly appears beyond the closed road. Mara Venn suspends traffic, Kellan Ro flies a permitted short-range search, and Zoe Mercer keeps families informed rather than repeating the unverified beacon location.

The rover reaches the sheltered gate with everyone aboard. The beacon continues to report a position several kilometers away for four more minutes. The immediate rescue is over, but transit cannot reopen the route until the false position has an explanation.','The school rover is safe, but its beacon kept moving on the map. What did each of you actually see?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['colony-wide','major-incident']::text[],'{"contentDigest":"594aba7e367e584c6ab967a51da31b0f558d578f22f1def1f0bcc6ef9cec71e7","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
  delete from public.together_world_pulse_template_participants where template_id = v_template;
  select id into strict v_character from public.together_character_templates where slug = 'mara-venn' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: eos-meridian/eleven-minutes-without-the-horizon/mara-venn'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,0,'Closed the road','I stopped every outbound vehicle when the school rover and its beacon disagreed. The delay stranded other people, and I would make the same call again.','The rover made it back. Why is the route still closed?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own role and observations. Do not claim to know another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'kellan-ro' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: eos-meridian/eleven-minutes-without-the-horizon/kellan-ro'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,1,'Searched the dust edge','I found the actual rover by its heat trace, not the map marker. I cannot say whether the beacon error began on the rover or in the relay.','What did you see from the air before the rover returned?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own role and observations. Do not claim to know another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'zoe-mercer' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: eos-meridian/eleven-minutes-without-the-horizon/zoe-mercer'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,2,'Updated the families','I told the waiting families what we had confirmed, even while they were asking for the map position. I still owe them an explanation of the false beacon.','How did you handle the wait with the families?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own role and observations. Do not claim to know another witness''s private reason."]}'::jsonb);
  select id into strict v_location from public.together_locations where world_id = v_world and slug = 'ascension-terminal' and owner_user_id is null and archived_at is null;
  select id into strict v_primary from public.together_character_templates where slug = 'commander-rhea-navarro' and published and creator_id is null;
  select id, repeat_identity, scheduling_rank, content_version, metadata into v_existing from public.together_world_pulse_templates where world_id = v_world and slug = 'ship-asking-for-shelter';
  if found and (v_existing.repeat_identity <> 'eos-meridian:major:ship-asking-for-shelter' or v_existing.scheduling_rank <> 201 or v_existing.content_version > 1 or coalesce(v_existing.metadata->>'pulseTier', 'routine') <> 'major') then raise exception 'Unsafe Pulse identity, rank, tier or version edit: eos-meridian/ship-asking-for-shelter'; end if;
  v_facts := '[]'::jsonb;
  select coalesce(jsonb_agg(id::text order by id), '[]'::jsonb) into v_known_ids from public.together_character_templates where slug = any(array['commander-rhea-navarro','leona-baptiste','mina-zhao','dr-lena-okafor']::text[]) and published and creator_id is null;
  if jsonb_array_length(v_known_ids) <> 4 then raise exception 'Unknown Pulse fact knower: eos-meridian/ship-asking-for-shelter/public-report'; end if;
  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','A damaged passenger ship with 41 people aboard requests an emergency berth. Port control can make room only by moving a scheduled departure and delaying a medical cargo transfer.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'ship-asking-for-shelter','eos-meridian:major:ship-asking-for-shelter',201,1,'A Ship Asking for Shelter','A damaged passenger ship with 41 people aboard requests an emergency berth. Port control can make room only by moving a scheduled departure and delaying a medical cargo transfer.','Ascension Port is Eos Meridian’s link to other settlements. A ship with a fractured radiator reports 41 passengers, enough fuel for one controlled approach, and no safe place to wait outside the port. Rhea Navarro orders one bay cleared. Leona Baptiste begins matching arriving households to temporary rooms, while Mina Zhao asks for the manifest before customs waives normal intake. Lena Okafor warns that the diverted bay was reserved for temperature-sensitive medical supplies.

The ship docks and the passengers come through the terminal. The medicine is transferred through a slower service route and remains within its safe temperature range, but the rescheduled departure loses its launch window. Port officials must decide who pays for the delay and whether the ship’s incomplete manifest was an emergency omission or something more.','The ship docked, but people lost a departure slot and the manifest is incomplete. What happened at each end of the terminal?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['colony-wide','major-incident']::text[],'{"contentDigest":"6e12f5ca79b8987afb17346312637fb5dbc9aee69fa71b5bfa14e68485b02b34","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
  delete from public.together_world_pulse_template_participants where template_id = v_template;
  select id into strict v_character from public.together_character_templates where slug = 'commander-rhea-navarro' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: eos-meridian/ship-asking-for-shelter/commander-rhea-navarro'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,0,'Cleared the berth','I accepted the docking risk and moved the scheduled departure. I know exactly whose plans that disrupted, but a damaged ship could not hold position.','Why did you give that ship the berth?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own role and observations. Do not claim to know another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'leona-baptiste' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: eos-meridian/ship-asking-for-shelter/leona-baptiste'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,1,'Placed arriving families','I had names and room needs before I had enough rooms. One family refused to be split, so I held an accessible suite open while I searched.','What happened to the passengers after they landed?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own role and observations. Do not claim to know another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'mina-zhao' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: eos-meridian/ship-asking-for-shelter/mina-zhao'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,2,'Checked the manifest','The manifest is incomplete in a way a rushed crew might explain. I will not label it fraud without asking the captain.','Was the missing manifest information suspicious?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own role and observations. Do not claim to know another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'dr-lena-okafor' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: eos-meridian/ship-asking-for-shelter/dr-lena-okafor'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,3,'Protected medical cargo','I signed off on the slower transfer only after a second temperature check. A successful delivery does not erase the risk that decision created.','Did the medical supplies arrive safely?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own role and observations. Do not claim to know another witness''s private reason."]}'::jsonb);
  select id into strict v_location from public.together_locations where world_id = v_world and slug = 'meridian-concourse' and owner_user_id is null and archived_at is null;
  select id into strict v_primary from public.together_character_templates where slug = 'dax-holloway' and published and creator_id is null;
  select id, repeat_identity, scheduling_rank, content_version, metadata into v_existing from public.together_world_pulse_templates where world_id = v_world and slug = 'every-exit-turns-red';
  if found and (v_existing.repeat_identity <> 'eos-meridian:major:every-exit-turns-red' or v_existing.scheduling_rank <> 202 or v_existing.content_version > 1 or coalesce(v_existing.metadata->>'pulseTier', 'routine') <> 'major') then raise exception 'Unsafe Pulse identity, rank, tier or version edit: eos-meridian/every-exit-turns-red'; end if;
  v_facts := '[]'::jsonb;
  select coalesce(jsonb_agg(id::text order by id), '[]'::jsonb) into v_known_ids from public.together_character_templates where slug = any(array['dax-holloway','amaya-flores','malik-orison','celeste-ren']::text[]) and published and creator_id is null;
  if jsonb_array_length(v_known_ids) <> 4 then raise exception 'Unknown Pulse fact knower: eos-meridian/every-exit-turns-red/public-report'; end if;
  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','Evacuation displays in three busy districts briefly mark every public exit unsafe. Staff guide people by posted physical routes while engineers isolate the faulty display network.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'every-exit-turns-red','eos-meridian:major:every-exit-turns-red',202,1,'Every Exit Turns Red','Evacuation displays in three busy districts briefly mark every public exit unsafe. Staff guide people by posted physical routes while engineers isolate the faulty display network.','Residents of Meridian Core, Forge Ward, and Old Meridian look up at once to see every electronic exit sign turn red. The doors still open, and independent pressure gauges show safe air. Dax Holloway isolates the display network from the actual door controls. Amaya Flores and Malik Orison guide crowds toward printed route maps while Celeste Ren drafts a public notice that distinguishes an alarming display failure from a verified evacuation.

The signs recover after nine minutes. No district was ordered to evacuate, yet several residents followed contradictory directions before staff reached them. The fault appears in a shared update channel; the colony now has to inspect who approved the update and whether the paper routes are still legible where they matter.','The doors worked while the signs said otherwise. How did each of you decide what to trust?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['colony-wide','major-incident']::text[],'{"contentDigest":"8cb3ad0d94508ec9959eef2baa15e1082a2f1ae0e088dd35424ccd28d54e2bee","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
  delete from public.together_world_pulse_template_participants where template_id = v_template;
  select id into strict v_character from public.together_character_templates where slug = 'dax-holloway' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: eos-meridian/every-exit-turns-red/dax-holloway'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,0,'Isolated the sign network','I verified the doors and pressure sensors separately before saying the exits were usable. I cannot yet attribute the bad update.','Were the exits actually unsafe?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own role and observations. Do not claim to know another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'amaya-flores' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: eos-meridian/every-exit-turns-red/amaya-flores'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,1,'Guided the crowd','People saw red and moved before the announcement finished. One paper map had been covered by a vendor display, and I reported it.','What was it like when all the signs changed?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own role and observations. Do not claim to know another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'malik-orison' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: eos-meridian/every-exit-turns-red/malik-orison'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,2,'Opened a safe route','I know the old corridor by memory, but I would rather people had a visible map than rely on me.','Where did you take people when the signs failed?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own role and observations. Do not claim to know another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'celeste-ren' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: eos-meridian/every-exit-turns-red/celeste-ren'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,3,'Wrote the public notice','My first draft sounded too certain. I changed it to say which systems were independently checked and which were still under review.','What did the colony actually tell residents?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own role and observations. Do not claim to know another witness''s private reason."]}'::jsonb);
  select id into strict v_location from public.together_locations where world_id = v_world and slug = 'ascension-port' and owner_user_id is null and archived_at is null;
  select id into strict v_primary from public.together_character_templates where slug = 'commander-rhea-navarro' and published and creator_id is null;
  select id, repeat_identity, scheduling_rank, content_version, metadata into v_existing from public.together_world_pulse_templates where world_id = v_world and slug = 'freighter-overhead';
  if found and (v_existing.repeat_identity <> 'eos-meridian:major:freighter-overhead' or v_existing.scheduling_rank <> 203 or v_existing.content_version > 1 or coalesce(v_existing.metadata->>'pulseTier', 'routine') <> 'major') then raise exception 'Unsafe Pulse identity, rank, tier or version edit: eos-meridian/freighter-overhead'; end if;
  v_facts := '[]'::jsonb;
  select coalesce(jsonb_agg(id::text order by id), '[]'::jsonb) into v_known_ids from public.together_character_templates where slug = any(array['commander-rhea-navarro','yara-kwon','zahra-benali']::text[]) and published and creator_id is null;
  if jsonb_array_length(v_known_ids) <> 3 then raise exception 'Unknown Pulse fact knower: eos-meridian/freighter-overhead/public-report'; end if;
  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','A cargo freighter misses its first braking mark and crosses the port approach below its approved altitude. It lands on the second attempt; nearby maintenance crews demand the flight data.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'freighter-overhead','eos-meridian:major:freighter-overhead',203,1,'The Freighter That Passed Too Low','A cargo freighter misses its first braking mark and crosses the port approach below its approved altitude. It lands on the second attempt; nearby maintenance crews demand the flight data.','A freighter carrying replacement habitat valves flashes across Ascension Port’s upper windows at an angle nobody expected. Rhea Navarro clears the flight corridor. Yara Kwon hears a rough pulse in the ship’s braking sequence from Hangar Twelve, while Zahra Benali stops unloading crews from entering the exposed apron. The freighter circles and lands without striking the port.

Its captain calls the first pass a sensor fault. Port telemetry and the ship’s own log disagree about when the missed mark became visible. The valves are needed for routine maintenance, but the port will not release the ship for another departure until a joint inspection is finished.','The ship landed, but its logs and port telemetry disagree. What should be checked before it flies again?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['colony-wide','major-incident']::text[],'{"contentDigest":"f6075c02fef545c1a9ee75cfdc3333d862951eba097d14b027e492c7a18b59a8","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
