  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','A red-storm lockdown seals both ends of a transit tunnel with a passenger train between them. Air and power hold, but the stranded riders cannot be released until crews confirm the outer seals.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'train-between-doors','eos-meridian:major:train-between-doors',204,1,'The Train Between Two Sealed Doors','A red-storm lockdown seals both ends of a transit tunnel with a passenger train between them. Air and power hold, but the stranded riders cannot be released until crews confirm the outer seals.','The tunnel train from Forge Ward is halfway to Meridian Core when storm shutters close at both ends. Mara Venn keeps the train powered and announces a two-hour air reserve rather than promising an arrival time. Milo Jensen carries a maintenance link through the service crawlway; Samira Cole organizes water and medication information from passengers without claiming the train is in immediate danger.

An outer seal passes inspection and the train reaches its platform ninety minutes later. Nobody needed emergency air. The incident leaves a harder question: why did the shutters close in the wrong order when the storm procedure requires the train to clear the tunnel first?','The train got out safely. Which part of the procedure failed, and who noticed first?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['colony-wide','major-incident']::text[],'{"contentDigest":"70a7ce9910157c683f8c7255ce2bc0200b98415141bd98a3ec30070717c2002f","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
