  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','A greenhouse roof seam opens during a pressure test, dropping a protective panel into an empty work lane. Growers secure the crops, but the main orchard path closes for inspection.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'solace-dome-seam','eos-meridian:major:solace-dome-seam',205,1,'A Seam Opens Above Solace','A greenhouse roof seam opens during a pressure test, dropping a protective panel into an empty work lane. Growers secure the crops, but the main orchard path closes for inspection.','In Solace Biome, food gardens grow beneath engineered roofs. A roof seam separates during a scheduled pressure test, and one transparent panel lands in a cleared maintenance lane. Imani Laurent calls a crop-protection shutdown. Elian Park reroutes humidity control while Liora Haddad moves the orchard crew out of the adjoining path. No one is hurt, and the produce remains usable.

The test record shows the seam was marked for a later repair, not an immediate closure. The orchards will operate on a narrower walkway until engineers inspect adjacent panels. Residents who rely on the harvest want to know why that repair was deferred.','The harvest survived, but the seam had already been flagged. Who decided it could wait?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['colony-wide','major-incident']::text[],'{"contentDigest":"8e787cdfd023bf650bd9c2de252eb60c2941bad9a07e5c72749d21c6941fd396","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
