  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'colony-goes-cold','eos-meridian:major:colony-goes-cold',206,1,'The Colony Goes Cold','A geothermal heat exchanger trips and several residential blocks lose heating. Backup circulation holds critical rooms while repair teams race the falling indoor temperatures.','Eos Meridian depends on geothermal loops for warmth along the cold twilight edge. A heat exchanger at Caldera trips, and apartment radiators in two districts begin cooling. Dax Holloway isolates the failed loop, Zoe Mercer checks medically vulnerable households, and Mateo Singh insists that repair crews rotate before fatigue creates a second fault.

A replacement pump restores circulation before any home becomes unsafe. Engineers recover a damaged bearing, but cannot yet tell whether the part failed early or its inspection interval was too long. The colony must decide how much backup heating it can afford to keep idle.','The heat is back. What did the repair reveal, and what should change before the next cold night?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['colony-wide','major-incident']::text[],'{"contentDigest":"92f7a628bd315c763aaeebfc42b8b2d03fb6ee4e1f9570d6a5d8e6421dfebc1a","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
