  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'ice-breaks-under-nightglass','eos-meridian:major:ice-breaks-under-nightglass',207,1,'The Ice Breaks Under Nightglass','A marked ice lane cracks beneath an unmanned research sled. The sled is recovered, but a nearby shelter closes while scientists and rescue crews disagree about the safe boundary.','Nightglass is Eos Meridian’s permanent-night research district. A routine sled carrying samples crosses a marked lane and drops through a new fissure; the nearby shelter was empty. Freya Solberg halts all crossings, Kenji Brooks checks the sheltered route on foot, and Priya Nwosu asks the team to preserve the sled’s intact depth readings before towing it out.

The sled comes back with its samples sealed. The fissure reaches farther than the last survey predicted, and the shelter remains closed. Researchers can still work from a safer station, but the next expedition must redraw its route before anyone crosses that ice again.','The sled is back and the shelter is closed. What does the crack change for the next expedition?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['colony-wide','major-incident']::text[],'{"contentDigest":"057ccc0a97c5150785caed9fd6a4e32f2c26d48e2a3d529f4c53e314c42535da","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
