  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'lyra-emergency-channel','eos-meridian:major:lyra-emergency-channel',208,1,'Lyra Speaks on the Emergency Channel','The sealed Habitat Lyra transmits a valid current maintenance code over an emergency band. No evacuation order follows, but port and archive staff must establish who still has that code.','Habitat Lyra is an old settlement section whose restricted areas have long been a source of rumor. During a routine emergency-band test, a transmitter identified as Lyra answers with a maintenance code still accepted by the colony system. Luc Moreau confirms that the code format is current; Jonah Sato searches the change record; Rhea Navarro prevents a curious crew from treating the signal as permission to enter a sealed corridor.

The transmission stops after one response. The code is valid, but that does not establish who sent it or whether anyone was inside Lyra. Security limits access to the transmitter route while the archive traces when the code was issued.','The code is current, but nobody knows who sent it. What can each of you actually verify?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['colony-wide','major-incident']::text[],'{"contentDigest":"07cda80c0e41fb48a87b9b6e07658e08e6d63943961573be39aea3eb9b496a2b","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
