  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'violet-sky','eos-meridian:major:violet-sky',209,1,'The Sky Turns Violet','A bright auroral disturbance silences the port relay for seventeen minutes. Shuttles hold safely, but families on both sides of the gap hear different fragments of the same warning.','The night edge of Eos glows violet as charged particles sweep across the upper atmosphere. Ascension Port loses its long-range relay for seventeen minutes while local guidance remains intact. Aya Nakamura confirms the disturbance on sky instruments, Rhea Navarro orders inbound shuttles into a holding pattern, and Leona Baptiste keeps waiting families from mistaking an incomplete alert for an accident.

Communications return and both shuttles land safely. One recorded warning began before the relay failed and ended after it returned; neither side heard the whole sentence live. Port staff publish the complete recording and review why the public channel carried a fragment without its correction.','Both shuttles landed. Why did the same warning sound different on each side of the relay gap?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['colony-wide','major-incident']::text[],'{"contentDigest":"abc9c1379c8194d87ad9ced5bc0971ec20400d8356e558258707610c2c5cc270","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
