  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'old-meridian-sleeps-elsewhere','eos-meridian:major:old-meridian-sleeps-elsewhere',211,1,'Old Meridian Sleeps Elsewhere','A pressure seam in an Old Meridian corridor forces households into temporary rooms overnight. The repair holds by morning, but residents dispute who gets to certify that home is safe again.','Old Meridian is the colony’s oldest lived-in district, full of patched interiors and residents who know every draft. A corridor seam begins leaking air faster than its automatic compensator can replace it. Malik Orison opens the diner as a gathering point, Camille Arden offers hotel rooms, and Naomi Varga orders a targeted overnight relocation rather than sealing an entire block.

Crews patch and test the seam before dawn. Households may return after an independent pressure reading, but some residents want their own representative present at the test. The argument is about trust in a repaired wall as much as the night spent away from home.','The seam is patched. Why do residents still want someone of their own at the pressure test?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['colony-wide','major-incident']::text[],'{"contentDigest":"bc69c63f837fd99415d2cc3abfa24677e52920e9516aa25e4544eccfc9e3191a","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
