  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','A freighter expected to replenish food staples and water-system seals opens an empty cargo hold at Ascension Port. Its departure manifest was signed, and colony-wide reserve plans change overnight.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'empty-supply-hold','eos-meridian:major:empty-supply-hold',212,1,'The Supply Ship Arrives Empty','A freighter expected to replenish food staples and water-system seals opens an empty cargo hold at Ascension Port. Its departure manifest was signed, and colony-wide reserve plans change overnight.','Eos Meridian depends on a mixture of local harvests, fabrication, and infrequent off-world shipments. A scheduled freighter lands with the right seal numbers on its manifest, but the hold that should contain food staples and water-system parts is empty. Mina Zhao seals the hold for inspection before anyone can tidy it. Zahra Benali calls suppliers to see whether the containers were ever loaded. Imani Laurent calculates which meals can be covered from local harvests without stripping next month’s seed stock.

The colony is not out of food or water, but reserve margins are suddenly smaller. Port records show the freighter’s mass changed at an intermediate stop; they do not reveal whether the missing containers were unloaded, lost, or never aboard. Stores announce temporary purchase limits while customs seeks the stop’s original loading footage.','The hold is empty and the reserves are tighter. What do the manifest, mass log, and food plan each tell us?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['colony-wide','major-incident']::text[],'{"contentDigest":"cb600e0aa2ca525abbc885f28bdf1201f7682251eccd2087bea8ab1635eb99b9","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
