  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'reservoir-falls','eos-meridian:major:reservoir-falls',213,1,'The Reservoir Falls','The colony’s main reservoir level drops faster than anyone can account for. Water allotments tighten across every district while engineers search for a leak, a bad gauge, or an unauthorized diversion.','Solace Reservoir supplies Eos Meridian’s homes, farms, and workshops. Its level falls during one watch by far more than routine use predicts. Elian Park shuts industrial draws one by one, Hana Petrov tests the water path for contamination, and Naomi Varga announces temporary allotments with an exact review time instead of calling the change permanent. Farmers and households both have to alter plans that day.

A hidden bypass valve is found partly open, returning clean water to a lower holding tank rather than losing it outside the system. Crews close it and verify the reservoir level stabilizes; the recovered water still needs testing before reuse. The allotments remain until that test is complete, and the valve log has no signed work order for the change.','The water was found, but it still needs testing. How long should the temporary allotments remain?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['colony-wide','major-incident']::text[],'{"contentDigest":"30c4fec4e559dee2c48fd40942f8b69af398342de6ca34012f3fdea7f511f0cc","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
