  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,0,'Located the bypass','The water was diverted within the system, which is better than a hull leak. I still cannot tell who opened the valve or why its status stayed unreported.','Where did the reservoir water go?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own role and observations. Do not claim to know another witness''s private reason."]}'::jsonb);
